def build_fills(D):
    """return dict of candidate outputs under different fallback rules"""
    hr = [i for i in range(30) if 8 in D[i]]
    hc = sorted({j for i in hr for j in range(30) if D[i][j]==8})
    def g(i,j): return D[i][j] if 0<=i<30 and 0<=j<30 else None
    res = {}
    def rowext(i,j):  # continue from donor 31-i in same direction
        d = 1 if 31-i > i else -1
        k = 31-i
        while 0<=k<30:
            if g(k,j) not in (8,None): return g(k,j)
            k += d
        return None
    def rowext_up(i,j):  # nearest clean scanning up then down? or up-first
        for k in range(i-1,-1,-1):
            if g(k,j) not in (8,None): return g(k,j)
        for k in range(i+1,30):
            if g(k,j) not in (8,None): return g(k,j)
    def rowext_near(i,j):  # nearest clean row either direction
        best=None
        for k in range(30):
            if g(k,j) not in (8,None):
                d=abs(k-i)
                if best is None or d<best[0]: best=(d,g(k,j))
        return best[1] if best else None
    rules = {
      'row_col_rowext':  lambda i,j: (g(31-i,j) if g(31-i,j) not in (8,None) else (g(i,31-j) if g(i,31-j) not in (8,None) else rowext(i,j))),
